// Validar archivos subidos
const request = $input.all()[0].json.body;
const files = request.files || [];
const userId = request.userId || 'anonymous';
const companyId = request.companyId;

if (!companyId) {
  throw new Error('Company ID is required');
}

if (files.length === 0) {
  throw new Error('No files provided');
}

const validatedFiles = [];
const supportedTypes = ['.xml', '.pdf', '.csv', '.xlsx', '.xls'];
const maxSizeBytes = 10 * 1024 * 1024; // 10MB

for (const file of files) {
  // Validar tipo de archivo
  const extension = file.name.toLowerCase().substring(file.name.lastIndexOf('.'));
  if (!supportedTypes.includes(extension)) {
    throw new Error(`Tipo de archivo no soportado: ${extension}. Tipos válidos: ${supportedTypes.join(', ')}`);
  }

  // Validar tamaño
  if (file.size > maxSizeBytes) {
    throw new Error(`Archivo muy grande: ${file.name}. Tamaño máximo: 10MB`);
  }

  // Determinar tipo de documento financiero
  let docType = 'unknown';
  if (extension === '.xml' && (file.name.includes('cfdi') || file.name.includes('factura'))) {
    docType = 'cfdi';
  } else if (file.name.toLowerCase().includes('estado') || file.name.toLowerCase().includes('bank')) {
    docType = 'bank_statement';
  } else if (file.name.toLowerCase().includes('balance') || file.name.toLowerCase().includes('contable')) {
    docType = 'accounting_report';
  } else if (extension === '.pdf') {
    docType = 'pdf_document';
  } else if (['.csv', '.xlsx', '.xls'].includes(extension)) {
    docType = 'spreadsheet';
  }

  validatedFiles.push({
    ...file,
    docType: docType,
    uploadId: 'UPLOAD_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    status: 'validated',
    uploadedAt: new Date().toISOString()
  });
}

return [{
  userId: userId,
  companyId: companyId,
  files: validatedFiles,
  totalFiles: validatedFiles.length,
  validationComplete: true,
  validationTime: new Date().toISOString()
}];

