  let bankName = 'Desconocido';
  if (file.name.toLowerCase().includes('bbva')) bankName = 'BBVA México';
  else if (file.name.toLowerCase().includes('santander')) bankName = 'Santander México';
  else if (file.name.toLowerCase().includes('banorte')) bankName = 'Banorte';
  else if (file.name.toLowerCase().includes('banamex')) bankName = 'Banamex';

  // Simular extracción de datos del estado de cuenta
  const bankData = {
    banco: bankName,
    numero_cuenta: '****' + Math.floor(Math.random() * 10000).toString().padStart(4, '0'),
    titular: data.companyId,
    periodo: {
      fecha_inicio: '2024-03-01',
      fecha_fin: '2024-03-31'
    },

    saldos: {
      inicial: 50000 + Math.random() * 50000,
      final: 45000 + Math.random() * 60000,
      promedio: 52000 + Math.random() * 8000
    },

    transacciones: [
      {
        fecha: '2024-03-15',
        descripcion: 'TRANSFERENCIA SPEI RECIBIDA',
        referencia: 'TRF001234',
        cargo: 0,
        abono: 25000.00,
        saldo: 75000.00,
        tipo: 'transferencia_recibida'
      },
      {
        fecha: '2024-03-16',
        descripcion: 'PAGO NOMINA EMPLEADOS',
        referencia: 'NOM001',
        cargo: 45000.00,
        abono: 0,
        saldo: 30000.00,
        tipo: 'pago_nomina'
      },
      {
        fecha: '2024-03-17',
        descripcion: 'PAGO SERVICIOS CFE',
        referencia: 'SER001',
        cargo: 8500.00,
        abono: 0,
        saldo: 21500.00,
        tipo: 'pago_servicios'
      },
      {
        fecha: '2024-03-18',
        descripcion: 'DEPOSITO EFECTIVO',
        referencia: 'DEP001',
        cargo: 0,
        abono: 15000.00,
        saldo: 36500.00,
        tipo: 'deposito_efectivo'
      }
    ],

    // Comisiones y cargos
    comisiones: [
      {
        concepto: 'Manejo de cuenta',
        importe: 350.00,
        fecha: '2024-03-31'
      },
      {
        concepto: 'Transferencia SPEI',
        importe: 3.50,
        fecha: '2024-03-15'
      }
    ],

    // Análisis automático
    analisis: {
      total_ingresos: 40000.00,
      total_egresos: 53850.00,
      flujo_neto: -13850.00,
      numero_transacciones: 4,
      transacciones_por_tipo: {
        ingresos: 2,
        egresos: 2,
        comisiones: 2
      },
      patron_flujo: 'negativo', // positivo, negativo, estable
      alertas: [
        'Flujo de efectivo negativo en el período',
        'Revisar pagos de nómina vs ingresos'
      ]
    }
  };

  processedBankStatements.push({
    uploadId: file.uploadId,
    originalFile: file,
    extractedData: bankData,
    processingStatus: 'completed',
    processingTime: new Date().toISOString(),
    reconciliation_ready: true,
    suggested_actions: [
      'Iniciar conciliación bancaria',
      'Revisar flujo de efectivo negativo',
      'Analizar patrones de gastos'
    ]
  });
}

return [{
  ...data,
  processed_bank_statements: processedBankStatements,
  bank_processing_complete: true,
  bank_count: processedBankStatements.length,
  total_flow: processedBankStatements.reduce((sum, stmt) => sum + stmt.extractedData.analisis.flujo_neto, 0)
}];

// Procesador para otros documentos financieros
const data = $input.all()[0].json;
const otherFiles = data.files.filter(f => !['cfdi', 'bank_statement'].includes(f.docType));
const processedDocuments = [];

for (const file of otherFiles) {
  let extractedData = {};
  let documentAnalysis = {};

  switch (file.docType) {
    case 'accounting_report':
      extractedData = {
        tipo_reporte: 'balance_general',
        periodo: '2024-03',
        activos: {
          circulantes: 250000,
          fijos: 180000,
          total: 430000
        },
        pasivos: {
          corto_plazo: 85000,
          largo_plazo: 120000,
          total: 205000
        },
        capital: {
          capital_social: 150000,
          utilidades_retenidas: 75000,
          total: 225000
        },
        ratios_financieros: {
          liquidez: 2.94, // activos_circulantes / pasivos_corto_plazo
          endeudamiento: 0.48, // pasivos_total / activos_total
          rentabilidad: 0.17 // utilidad_neta / capital_total
        }
      };
      documentAnalysis = {
        salud_financiera: 'buena',
        alertas: [],
        recomendaciones: [
          'Mantener nivel de liquidez actual',
          'Evaluar oportunidades de inversión'
        ]
      };
      break;

    case 'spreadsheet':
      extractedData = {
        tipo_hoja: 'datos_financieros',
        filas_detectadas: Math.floor(Math.random() * 500) + 50,
        columnas_detectadas: Math.floor(Math.random() * 20) + 5,
        datos_numericos: true,
        fechas_detectadas: true,
        monedas_detectadas: ['MXN', 'USD'],
        categorias_identificadas: [
          'ingresos',
          'gastos',
          'nomina',
          'impuestos'
        ]
      };
      documentAnalysis = {
        calidad_datos: 'alta',
        completitud: '95%',
        sugerencias: [
          'Validar fórmulas de Excel',
          'Revisar formato de fechas'
        ]
      };
      break;

    case 'pdf_document':
    default:
      extractedData = {
        paginas: Math.floor(Math.random() * 20) + 1,
        texto_extraido: true,
        tablas_detectadas: Math.floor(Math.random() * 5),
        numeros_identificados: true,
        fechas_identificadas: true,
        firmas_digitales: Math.random() > 0.5
      };
      documentAnalysis = {
        legibilidad: 'alta',
        contenido_financiero: true,
        requiere_revision_manual: false
      };
      break;
  }

  processedDocuments.push({
    uploadId: file.uploadId,
    originalFile: file,
    extractedData: extractedData,
    analysis: documentAnalysis,
    processingStatus: 'completed',
    processingTime: new Date().toISOString(),
    next_steps: [
      'Indexar en base de conocimiento',
      'Crear embeddings para RAG',
      'Notificar usuario de procesamiento completo'
    ]
  });
}

return [{
  ...data,
  processed_other_documents: processedDocuments,
  other_processing_complete: true,
  other_count: processedDocuments.length
}];

// Indexar documentos en base de conocimiento para RAG
const data = $input.all()[0].json;
const allProcessedDocs = [
  ...(data.processed_cfdis || []),
  ...(data.processed_bank_statements || []),
  ...(data.processed_other_documents || [])
];

const knowledgeBaseEntries = [];

for (const doc of allProcessedDocs) {
  // Crear entrada para base de conocimiento
  const kbEntry = {
    id: doc.uploadId,
    company_id: data.companyId,
    document_type: doc.originalFile.docType,
    original_filename: doc.originalFile.name,

    // Contenido para embedding
    content_for_embedding: '',

    // Metadatos para filtering
    metadata: {
      upload_date: doc.processingTime,
      file_size: doc.originalFile.size,
      processing_status: doc.processingStatus,
      document_category: doc.originalFile.docType,
      language: 'es-MX',
      currency: 'MXN'
    },

    // Datos estructurados extraídos
    structured_data: doc.extractedData
  };

  // Generar contenido textual para embeddings según tipo de documento
  if (doc.originalFile.docType === 'cfdi') {
    const cfdi = doc.extractedData;
    kbEntry.content_for_embedding = `
Factura electrónica CFDI ${cfdi.folio} por $${cfdi.total} MXN.
Emisor: ${cfdi.emisor.nombre} (RFC: ${cfdi.emisor.rfc})
Receptor: ${cfdi.receptor.nombre} (RFC: ${cfdi.receptor.rfc})
Fecha: ${cfdi.fecha_emision}
Conceptos: ${cfdi.conceptos.map(c => c.descripcion).join(', ')}
Subtotal: $${cfdi.subtotal} MXN, IVA: $${cfdi.impuestos.iva.importe} MXN, Total: $${cfdi.total} MXN
UUID: ${cfdi.uuid}
Régimen fiscal emisor: ${cfdi.emisor.regimen_fiscal}
Uso CFDI: ${cfdi.receptor.uso_cfdi}
    `.trim();

  } else if (doc.originalFile.docType === 'bank_statement') {
    const bank = doc.extractedData;
    kbEntry.content_for_embedding = `
Estado de cuenta bancario ${bank.banco} cuenta ${bank.numero_cuenta}.
Titular: ${bank.titular}
Período: ${bank.periodo.fecha_inicio} al ${bank.periodo.fecha_fin}
Saldo inicial: $${bank.saldos.inicial} MXN, Saldo final: $${bank.saldos.final} MXN
Transacciones: ${bank.transacciones.length}
Ingresos totales: $${bank.analisis.total_ingresos} MXN
Egresos totales: $${bank.analisis.total_egresos} MXN
Flujo neto: $${bank.analisis.flujo_neto} MXN
Transacciones principales: ${bank.transacciones.map(t => `${t.fecha}: ${t.descripcion} $${t.cargo || t.abono} MXN`).join(', ')}
    `.trim();

  } else {
    // Para otros documentos, usar información general
    kbEntry.content_for_embedding = `
Documento financiero: ${doc.originalFile.name}
Tipo: ${doc.originalFile.docType}
Empresa: ${data.companyId}
Fecha de procesamiento: ${doc.processingTime}
Datos extraídos: ${JSON.stringify(doc.extractedData)}
    `.trim();
  }

  knowledgeBaseEntries.push(kbEntry);
}

// Preparar para envío a vector store
const vectorStorePayload = {
  company_id: data.companyId,
  entries: knowledgeBaseEntries,
  total_entries: knowledgeBaseEntries.length,
  indexing_timestamp: new Date().toISOString(),
  embedding_model: 'text-embedding-3-small',
  chunk_strategy: 'document_based'
};

return [{
  ...data,
  knowledge_base_entries: knowledgeBaseEntries,
  vector_store_payload: vectorStorePayload,
  indexing_complete: true,
  ready_for_rag: true
}];

// Generar respuesta de procesamiento completado
const data = $input.all()[0].json;

// Calcular estadísticas de procesamiento
const stats = {
  total_files: data.totalFiles,
  cfdis_processed: data.cfdi_count || 0,
  bank_statements_processed: data.bank_count || 0,
  other_documents_processed: data.other_count || 0,
  total_cfdi_amount: data.total_amount_cfdis || 0,
  total_bank_flow: data.total_flow || 0,
  processing_time: Date.now() - new Date(data.validationTime).getTime(),
  knowledge_base_entries: data.knowledge_base_entries?.length || 0
};

// Generar insights automáticos
const insights = [];
if (stats.cfdis_processed > 0) {
  insights.push(`✅ Procesados ${stats.cfdis_processed} CFDIs por un total de $${stats.total_cfdi_amount.toLocaleString('es-MX')} MXN`);
}
if (stats.bank_statements_processed > 0) {
  const flowStatus = stats.total_bank_flow >= 0 ? '📈 positivo' : '📉 negativo';
  insights.push(`🏦 Analizados ${stats.bank_statements_processed} estados de cuenta con flujo ${flowStatus} de $${Math.abs(stats.total_bank_flow).toLocaleString('es-MX')} MXN`);
}
if (stats.knowledge_base_entries > 0) {
  insights.push(`🧠 Indexados ${stats.knowledge_base_entries} documentos en base de conocimiento para consultas RAG`);
}

// Generar acciones recomendadas
const recommendedActions = [];
if (stats.cfdis_processed > 0 && stats.bank_statements_processed > 0) {
  recommendedActions.push({
    action: 'start_reconciliation',
    label: '🔄 Iniciar conciliación bancaria',
    description: 'Reconciliar CFDIs procesados con estados de cuenta',
    priority: 'high',
    endpoint: '/api/reconciliation/start'
  });
}

if (stats.total_cfdi_amount > 0) {
  recommendedActions.push({
    action: 'generate_tax_report',
    label: '📊 Generar reporte fiscal',
    description: 'Crear reporte de ingresos/gastos para SAT',
    priority: 'medium',
    endpoint: '/api/reports/tax'
  });
}

recommendedActions.push({
  action: 'chat_with_data',
  label: '💬 Consultar datos con IA',
  description: 'Hacer preguntas sobre los documentos procesados',
  priority: 'low',
  endpoint: '/api/chat/financial'
});

// Respuesta final
const response = {
  success: true,
  processing_complete: true,
  company_id: data.companyId,
  user_id: data.userId,

  summary: {
    files_processed: stats.total_files,
    processing_time_ms: stats.processing_time,
    total_cfdi_value_mxn: stats.total_cfdi_amount,
    net_bank_flow_mxn: stats.total_bank_flow,
    knowledge_entries_created: stats.knowledge_base_entries
  },

  breakdown: {
    cfdis: {
      count: stats.cfdis_processed,
      total_amount: stats.total_cfdi_amount,
      status: stats.cfdis_processed > 0 ? 'completed' : 'none'
    },
    bank_statements: {
      count: stats.bank_statements_processed,
      net_flow: stats.total_bank_flow,
      status: stats.bank_statements_processed > 0 ? 'completed' : 'none'
    },
    other_documents: {
      count: stats.other_documents_processed,
      status: stats.other_documents_processed > 0 ? 'completed' : 'none'
    }
  },

  insights: insights,
  recommended_actions: recommendedActions,

  next_steps: [
    'Los documentos están disponibles para consultas RAG',
    'Puedes iniciar conciliación bancaria si tienes tanto CFDIs como estados de cuenta',
    'Genera reportes ejecutivos con los datos procesados',
    'Configura alertas automáticas para nuevos documentos'
  ],

  rag_ready: true,
  reconciliation_ready: stats.cfdis_processed > 0 && stats.bank_statements_processed > 0,

  mexican_compliance: {
    sat_cfdi_compatible: true,
    banking_format_supported: true,
    currency: 'MXN',
    timezone: 'America/Mexico_City'
  },

  timestamp: new Date().toISOString()
};

return [response];
